use std::collections::HashMap;

mkdeclfn! {
fn main () -> Result < () > { let cli = Cli :: parse () ; let config = GLOBAL_CONFIG . lock () . unwrap () ; let mut members = Vec :: new () ; for entry in WalkDir :: new (& cli . output_dir) . max_depth (1) { let entry = entry ? ; if entry . path () . is_dir () { if let Some (name) = entry . path () . file_name () . and_then (| n | n . to_str ()) { if name . starts_with ("wrapped-") { members . push (format ! ("\"{}\"" , name)) ; } } } } members . sort () ; let mut workspace_deps = HashMap :: new () ; for crate_name in & config . wrapping . crates { if let Some (path_override) = config . crate_path_overrides . as_ref () . and_then (| map | map . get (crate_name)) { if path_override . to_string_lossy () == "*" { let overrides = & config . workspace_dependency_overrides ; if ! overrides . is_empty () { if let Some (override_spec) = overrides . get (crate_name) { let toml_string = toml :: to_string (override_spec) ? ; workspace_deps . insert (crate_name . clone () , toml_string . trim () . to_string ()) ; } else { workspace_deps . insert (crate_name . clone () , "{ version = \"*\" }" . to_string ()) ; } } else { workspace_deps . insert (crate_name . clone () , "{ version = \"*\" }" . to_string ()) ; } } else { let path_str = path_override . to_string_lossy () ; let relative_path = if path_str . contains ("/submodules/") { let parts : Vec < & str > = path_str . split ("/submodules/") . collect () ; if parts . len () == 2 { format ! ("../submodules/{}" , parts [1]) } else { format ! ("../{}" , crate_name) } } else { format ! ("../{}" , crate_name) } ; workspace_deps . insert (crate_name . clone () , format ! ("{{ path = \"{}\" }}" , relative_path)) ; } } else { workspace_deps . insert (crate_name . clone () , format ! ("{{ path = \"../submodules/{}\" }}" , crate_name)) ; } } println ! ("Scanning wrapped crates for missing dependencies...") ; let mut missing_deps = std :: collections :: HashSet :: new () ; for entry in WalkDir :: new (& cli . output_dir) . max_depth (2) { let entry = entry ? ; if entry . file_name () == "Cargo.toml" && entry . path () != cli . output_dir . join ("Cargo.toml") { if let Ok (content) = fs :: read_to_string (entry . path ()) { if let Ok (cargo_toml) = toml :: from_str :: < toml :: Value > (& content) { for section in ["dependencies" , "build-dependencies" , "dev-dependencies"] { if let Some (deps) = cargo_toml . get (section) . and_then (| v | v . as_table ()) { for (dep_name , dep_value) in deps { if let Some (table) = dep_value . as_table () { if table . get ("workspace") == Some (& toml :: Value :: Boolean (true)) { missing_deps . insert (dep_name . clone ()) ; } } } } } } } } } for dep_name in missing_deps { if ! workspace_deps . contains_key (& dep_name) { workspace_deps . insert (dep_name . clone () , "{ version = \"*\" }" . to_string ()) ; } } let overrides = & config . workspace_dependency_overrides ; if ! overrides . is_empty () { for (name , override_spec) in overrides { if ! workspace_deps . contains_key (name) { let toml_string = toml :: to_string (override_spec) ? ; workspace_deps . insert (name . clone () , toml_string . trim () . to_string ()) ; } } } let mut workspace_content = String :: new () ; workspace_content . push_str ("# Generated workspace Cargo.toml from split-decls-rs.toml configuration\n\n") ; workspace_content . push_str ("[workspace]\n") ; workspace_content . push_str ("resolver = \"2\"\n") ; workspace_content . push_str ("members = [\n") ; for member in & members { workspace_content . push_str (& format ! ("    {},\n" , member)) ; } workspace_content . push_str ("]\n\n") ; workspace_content . push_str ("[workspace.dependencies]\n") ; let mut sorted_deps : Vec < _ > = workspace_deps . iter () . collect () ; sorted_deps . sort_by_key (| (name , _) | * name) ; for (name , spec) in sorted_deps { workspace_content . push_str (& format ! ("{} = {}\n" , name , spec)) ; } let workspace_path = cli . output_dir . join ("Cargo.toml") ; fs :: write (& workspace_path , workspace_content) ? ; println ! ("✅ Generated workspace with {} members and {} dependencies using split-decls-rs.toml" , members . len () , workspace_deps . len ()) ; Ok (()) }
}